app.get('/api/targets',auth(),route(async(r,s)=>{
  const u=r.user,{month,from,to,year}=range(r.query);
  const monthDate=new Date(month+'-01T00:00:00'),monthEnd=new Date(monthDate.getFullYear(),monthDate.getMonth()+1,0);
  const monthTo=`${monthEnd.getFullYear()}-${String(monthEnd.getMonth()+1).padStart(2,'0')}-${String(monthEnd.getDate()).padStart(2,'0')}`;
  const firstYear=Number(from.slice(0,4)),lastYear=Number(to.slice(0,4)),monthFrom=month+'-01';
  const con=['Bendahara','Administrasi','Sekretaris','Ketua'].includes(u.division)&&r.query.consolidated==='1';
  const d=division(u,r.query.division);
  let where='t.active=1 AND t.target_year BETWEEN ? AND ?',params=[monthFrom,monthTo,from,to,firstYear,lastYear];
  if(!con&&(!all(u)||d)){where+=' AND t.division=?';params.push(d)}
  else if(con&&u.division==='Administrasi')where+=" AND t.division NOT IN ('Ketua','Sekretaris')";
  else if(con&&u.division==='Bendahara')where+=" AND t.division NOT IN ('Ketua','Sekretaris','Administrasi')";
  const items=await q(`SELECT t.id,t.division,t.program,t.target_type,t.period,t.target_year,t.target_value,t.unit,t.note,
    COALESCE(SUM(CASE WHEN t.target_type<>'uang' AND YEAR(w.week_start)=t.target_year AND w.note NOT LIKE 'Keuangan:%' THEN w.actual_value ELSE 0 END),0) actual_year,
    COALESCE(SUM(CASE WHEN t.target_type<>'uang' AND w.week_start BETWEEN ? AND ? AND w.note NOT LIKE 'Keuangan:%' THEN w.actual_value ELSE 0 END),0) actual_month,
    COALESCE(SUM(CASE WHEN t.target_type<>'uang' AND w.week_start BETWEEN ? AND ? AND w.note NOT LIKE 'Keuangan:%' THEN w.actual_value ELSE 0 END),0) actual_range
    FROM targets t LEFT JOIN weekly_reports w ON w.target_id=t.id
    WHERE ${where}
    GROUP BY t.id,t.division,t.program,t.target_type,t.period,t.target_year,t.target_value,t.unit,t.note
    ORDER BY t.target_year,t.id`,params);
  if(items.length){
    const income=await q(`SELECT YEAR(transaction_date) target_year,division,category,
      COALESCE(SUM(amount),0) actual_year,
      COALESCE(SUM(CASE WHEN transaction_date BETWEEN ? AND ? THEN amount ELSE 0 END),0) actual_month,
      COALESCE(SUM(CASE WHEN transaction_date BETWEEN ? AND ? THEN amount ELSE 0 END),0) actual_range
      FROM transactions WHERE transaction_type='pemasukan' AND transaction_date BETWEEN ? AND ? GROUP BY YEAR(transaction_date),division,category`,[monthFrom,monthTo,from,to,`${firstYear}-01-01`,`${lastYear}-12-31`]);
    const targetsByKey=new Map();
    for(const item of items){const key=`${item.target_year}\u0000${item.division}\u0000${item.program}`,list=targetsByKey.get(key)||[];list.push(item);targetsByKey.set(key,list)}
    for(const row of income){
      const key=`${row.target_year}\u0000${row.division}\u0000${incomeTargetProgram(row.division,row.category)}`;
      for(const item of targetsByKey.get(key)||[]){
        item.actual_year+=Number(row.actual_year||0);
        item.actual_month+=Number(row.actual_month||0);
        item.actual_range+=Number(row.actual_range||0);
      }
    }
  }
  const fiscalYears=await q('SELECT fiscal_year,status FROM fiscal_years WHERE fiscal_year BETWEEN ? AND ? ORDER BY fiscal_year',[firstYear,lastYear]);
  s.json({items,division:con?'Seluruh unit':d,year,month,date_from:from,date_to:to,fiscal_years:fiscalYears});
}));
