async function budgetFinanceReport(u,query){
  const{from,to}=range(query);let where=` WHERE (
    LEFT(b.created_at,10) BETWEEN ? AND ? OR
    (b.disbursed_at<>'' AND LEFT(b.disbursed_at,10) BETWEEN ? AND ?) OR
    EXISTS(SELECT 1 FROM budget_usages pu WHERE pu.budget_request_id=b.id AND pu.usage_date BETWEEN ? AND ?) OR
    b.status NOT IN ('completed','rejected')
  )`,params=[from,to,from,to,from,to];
  if(!canViewCentralBudget(u)){where+=' AND b.division=?';params.push(u.division)}
  const items=await q(`SELECT b.*,q.name requester_name,
    COALESCE((SELECT SUM(au.amount) FROM budget_usages au WHERE au.budget_request_id=b.id),0) used_amount,
    COALESCE((SELECT SUM(pu.amount) FROM budget_usages pu WHERE pu.budget_request_id=b.id AND pu.usage_date BETWEEN ? AND ?),0) period_used
    FROM budget_requests b JOIN users q ON q.id=b.requester_id${where} ORDER BY b.id DESC`,[from,to,...params]);
  for(const item of items){item.remaining_amount=Math.max(0,Number(item.disbursed_amount)-Number(item.used_amount));item.usages=await q(`SELECT bu.id,bu.usage_date,bu.category,bu.amount,bu.description,bu.proof_note,u.name recorded_by
    FROM budget_usages bu JOIN users u ON u.id=bu.user_id WHERE bu.budget_request_id=? AND bu.usage_date BETWEEN ? AND ? ORDER BY bu.usage_date,bu.id`,[item.id,from,to])}
  const inPeriod=value=>value&&String(value).slice(0,10)>=from&&String(value).slice(0,10)<=to,summary={
    requested:items.filter(item=>inPeriod(item.created_at)).reduce((sum,item)=>sum+Number(item.amount),0),
    disbursed:items.filter(item=>inPeriod(item.disbursed_at)).reduce((sum,item)=>sum+Number(item.disbursed_amount),0),
    used:items.reduce((sum,item)=>sum+Number(item.period_used),0),
    outstanding:items.reduce((sum,item)=>sum+Number(item.remaining_amount),0),
    request_count:items.length
  };
  return{items,summary,date_from:from,date_to:to,access_scope:canViewCentralBudget(u)?'central':'unit'}
}
